import { test, expect } from '@playwright/test';
// Generated by brakes qa as a seed: this file is yours after the first install.
// The screenshot is taken of a settled page (docs/agent-setup/qa.md): network quiet,
// fonts loaded, content that appears on scroll revealed, animations disabled.
test('home renders and matches the baseline', async ({ page }) => {
  await page.goto('/');
  await expect(page).toHaveTitle(/.+/);
  await page.waitForLoadState('networkidle');
  await page.evaluate(async () => { await document.fonts.ready; });
  await page.evaluate(async () => {
    const frame = () => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
    for (let y = 0; y < document.documentElement.scrollHeight; y += window.innerHeight) {
      window.scrollTo(0, y);
      await frame();
    }
    window.scrollTo(0, 0);
    await frame();
  });
  await expect(page).toHaveScreenshot('home.png', { fullPage: true, animations: 'disabled' });
});
